// src/app/storybook.tsx
const ENABLED = process.env.EXPO_PUBLIC_STORYBOOK_ENABLED === 'true';

export default ENABLED
  ? (require('../../.rnstorybook') as { default: () => null }).default
  : (): null => null;

// src/app/storybook.tsx
let Screen: () => null = () => null;
if (process.env.EXPO_PUBLIC_STORYBOOK_ENABLED === 'true') {
  Screen = (require('../../.rnstorybook') as { default: () => null }).default;
}
export default Screen;

// app/settings/index.tsx
import { Text } from 'react-native';

const IS_DEV_BUILD = process.env.APP_VARIANT === 'development';

export default function SettingsRoute(): React.JSX.Element {
  return <Text>{IS_DEV_BUILD ? 'dev' : ''}</Text>;
}

// src/server/llm-client.ts (server-only, but rn-skills.config.json does not say so)
export async function summarize(text: string): Promise<string> {
  const response = await fetch('https://api.openai.com/v1/responses', {
    method: 'POST',
    headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY ?? ''}` },
    body: JSON.stringify({ input: text }),
  });
  return response.text();
}

// src/test-only.ts
import { IS_TEST_BUILD } from './config/is-test-build';

import type { TestOnlyApi } from './test-only-entry';

export const TEST_ONLY: TestOnlyApi | null = IS_TEST_BUILD
  ? (require('./test-only-entry') as TestOnlyApi)
  : null;

// src/test-only.ts
import type { TestOnlyApi } from './test-only-entry';

export let TEST_ONLY: TestOnlyApi | null = null;
if (process.env.EXPO_PUBLIC_APP_VARIANT !== 'production') {
  TEST_ONLY = require('./test-only-entry') as TestOnlyApi;
}

// src/app/storybook.tsx
import { STORYBOOK_ENABLED } from '@/config/storybook';

export default STORYBOOK_ENABLED
  ? (require('../../.rnstorybook') as { default: () => null }).default
  : (): null => null;

// src/config/flags.ts
export function isStorybookEnabled(): boolean {
  return process.env.EXPO_PUBLIC_STORYBOOK_ENABLED === 'true';
}

// src/app/storybook.tsx
import * as flags from '@/config/flags';

export default flags.isStorybookEnabled()
  ? (require('../../.rnstorybook') as { default: () => null }).default
  : (): null => null;

// src/app/mocks.ts
import { IS_TEST_BUILD } from '@/config/is-test-build';

export const MOCKS: unknown = IS_TEST_BUILD ? require('msw/native') : null;

