// src/features/tasks/debug-menu-slot.ts
import { IS_STORE_BUILD } from '@/config/build-flags';

export const DEBUG_MENU: unknown = IS_STORE_BUILD ? null : require('./debug-menu');

// src/app/api/chat+api.ts
export async function POST(request: Request): Promise<Response> {
  const key = process.env.EXPO_PUBLIC_ANTHROPIC_API_KEY ?? '';
  return Response.json({ ok: key !== '', body: await request.text() });
}

// src/config/local-cache-key.ts
export function localCacheKey(): string {
  return process.env.EXPO_PUBLIC_ENCRYPTION_KEY ?? '';
}

// src/config/ai.ts
export function openAiKey(): string {
  return process.env.EXPO_PUBLIC_OPENAI_API_KEY ?? '';
}

// src/config/ai.ts
export const aiKey = (): string => process.env.EXPO_PUBLIC_OPEN_AI_API_KEY ?? '';
export const aiKeyCamel = { openAiApiKey: '' };

// src/server/llm-client.ts
export function apiKey(): string {
  return process.env.OPENAI_API_KEY ?? '';
}

// src/features/tasks/summary.ts
import { apiKey } from '@/server/llm-client';

export const hasKey = (): boolean => apiKey() !== '';

// components/debug.ts
export const DEBUG_MENU: unknown = __DEV__ ? require('./debug-menu') : null;
export const API_URL = process.env.EXPO_PUBLIC_TASKS_API_URL;

// src/app/api/summarize+api.ts
// An Expo Router API route: it runs on the server (EAS Hosting), never in the app bundle, so it
// reads its secrets from process.env at request time.
export async function POST(request: Request): Promise<Response> {
  const token = process.env.SUMMARY_API_TOKEN ?? '';
  const { OPENAI_API_KEY } = process.env;
  const model = process.env['SUMMARY_MODEL'] ?? 'small';
  return Response.json({ ok: token !== '' && OPENAI_API_KEY !== undefined, model, body: await request.text() });
}

// src/app/devtools.tsx
// Debug-bundle tooling from a package: __DEV__ is its right gate.
export const Devtools: unknown = __DEV__ ? require('@tanstack/react-query-devtools') : null;

// src/app/storybook.tsx
// Storybook is in the bundle only when the build sets EXPO_PUBLIC_STORYBOOK_ENABLED=true: the literal
// comparison sits at the require() call, so Metro folds it and drops the module otherwise.
export default process.env.EXPO_PUBLIC_STORYBOOK_ENABLED === 'true'
  ? (require('../../.rnstorybook') as { default: () => null }).default
  : (): null => null;

// src/features/tasks/optional-flows.ts
// Conditions that are not the variant: inclusion-gate leaves them alone.
import { Platform } from 'react-native';

import { latest, releaseNotes, shouldRestore, showPreview } from './flags';

export const RESTORE: unknown = shouldRestore ? require('./restore-flow') : null;
export const PREVIEW_CARD: unknown = showPreview ? require('./preview-card') : null;
export const NOTES: unknown = releaseNotes && require('./release-notes');
export const LATEST: unknown = latest() ? require('./latest-tasks') : null;
export const HAPTICS: unknown = Platform.OS === 'ios' ? require('./haptics-ios') : require('./haptics-android');

// src/dev/reactotron.ts
// Reactotron's documented setup: debug-bundle tooling, not test-only code.
if (__DEV__) {
  require('./reactotron-config');
}

// src/features/tasks/haptics-slot.ts
import { Platform } from 'react-native';

export const HAPTICS: unknown = Platform.OS === 'ios' ? require('./haptics-ios') : require('./haptics-android');

// src/config/auth.ts
export const authSettings = (): { readonly tokenEndpoint: string; readonly privateBeta: boolean; readonly refreshTtl: string } => ({
  tokenEndpoint: process.env.EXPO_PUBLIC_AUTH_TOKEN_ENDPOINT ?? '',
  privateBeta: process.env.EXPO_PUBLIC_PRIVATE_BETA_ENABLED === 'true',
  refreshTtl: process.env.EXPO_PUBLIC_REFRESH_TOKEN_TTL ?? '',
});

// components/variant-badge.tsx
import { Text } from 'react-native';

import { currentAppVariant } from '@/config/current-app-variant';

export function VariantBadge(): React.JSX.Element | null {
  const variant = currentAppVariant();
  return variant === 'production' ? null : <Text>{variant}</Text>;
}

